"content": "import sys

def main():
    data = sys.stdin.read().strip().split()
    if len(data) < 4:
        return
    a, b, m, r0 = map(int, data[:4])
    seen = {r0: 0}
    cur = r0
    i = 0
    while True:
        i += 1
        cur = (a * cur + b) % m
        if cur in seen:
            period = i - seen[cur]
            print(period)
            return
        seen[cur] = i

if __name__ == "__main__":
    main()
